{"compatibility":"as-is","safety_note_md":"# SafeStan Safety Note

Compatibility: as-is.

Protected data: `y`.

Generated files: `model_safe.stan`, `data_safe.json`.

No changes were required. The protected observation `y` is a top-level data variable and is observed exactly once with a plain built-in sampling statement. All parameters have one built-in prior sampling statement before their use in the likelihood. Other data variables (`N`, `N_cov`, `w`, `x`, and `xw_inter`) are context inputs used as dimensions or predictors and are not protected.
","model_safe_stan":"functions {
  real quantile_user_defined(vector x, real p) {
    int n; // length of vector x
    real index; // integer index of p
    int lo; // lower integer cap of the index
    int hi; // higher integer cap of the index
    real h; // generated weight between the lo and hi
    real qs; // weighted average of x[lo] and x[hi]
    n = num_elements(x);
    index = 1 + (n - 1) * p;
    lo = 1;
    while ((lo + 1) < index) {
      lo = lo + 1;
    }
    hi = lo + 1;
    h = index - lo;
    qs = (1 - h) * sort_asc(x)[lo] + h * sort_asc(x)[hi];
    return qs;
  }
}
data {
  int<lower=0> N; // sample size
  int<lower=0> N_cov; // number of covariates
  vector[N] y; // observed outcome
  vector[N] w; // treatment assigned
  matrix[N, N_cov] x; // covariates
  matrix[N, N_cov] xw_inter; // interaction terms
}
parameters {
  real alpha; // intercept
  vector[N_cov] beta; // coefficients for x[N]
  vector[N_cov] beta_inter; // coefficients for x_inter[N] 
  real tau; // super-population average treatment effect
  real<lower=0> sigma_t; // residual SD for the treated
  real<lower=0> sigma_c; // residual SD for the control
}
model {
  // PRIORS
  alpha ~ normal(0, 100);
  beta ~ normal(0, 100);
  beta_inter ~ normal(0, 100);
  tau ~ normal(0, 100);
  sigma_c ~ normal(0, 100);
  sigma_t ~ normal(0, 100);
  // sigma_c ~ inv_gamma(1, 0.01);          
  // sigma_t ~ inv_gamma(1, 0.01);

  // LIKELIHOOD
  y ~ normal(alpha + x * beta + xw_inter * beta_inter + tau * w,
             sigma_t * w + sigma_c * (1 - w));
}
generated quantities {
  real tau_fs; // finite-sample average treatment effect
  real tau_qte25; // quantile treatment effect at p = 0.25
  real tau_qte50; // quantile treatment effect at p = 0.50
  real tau_qte75; // quantile treatment effect at p = 0.75
  array[N] real y0; // potential outcome if W = 0
  array[N] real y1; // potential outcome if W = 1
  array[N] real tau_unit; // unit-level treatment effect
  for (n in 1 : N) {
    real mu_t = alpha + x[n,  : ] * beta + x[n,  : ] * beta_inter + tau;
    real mu_c = alpha + x[n,  : ] * beta;
    if (w[n] == 1) {
      y0[n] = normal_rng(mu_c, sigma_c);
      y1[n] = y[n];
    } else {
      y0[n] = y[n];
      y1[n] = normal_rng(mu_t, sigma_t);
    }
    tau_unit[n] = y1[n] - y0[n];
  }
  tau_fs = mean(tau_unit);
  tau_qte25 = quantile_user_defined(to_vector(y1), 0.25)
              - quantile_user_defined(to_vector(y0), 0.25);
  tau_qte50 = quantile_user_defined(to_vector(y1), 0.50)
              - quantile_user_defined(to_vector(y0), 0.50);
  tau_qte75 = quantile_user_defined(to_vector(y1), 0.75)
              - quantile_user_defined(to_vector(y0), 0.75);
}
